<?php
declare(strict_types=1);require_once __DIR__.'/src/auth.php';require_admin();$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$s=$pdo->prepare('INSERT INTO admins(username,password_hash,role,created_at,is_active) VALUES(?,?,?,NOW(),1)');$s->execute([trim($_POST['username']),password_hash($_POST['password'],PASSWORD_DEFAULT),$_POST['role']]);$msg='Admin added successfully.';}catch(PDOException $e){$msg='Username already exists.';}}
$rows=$pdo->query('SELECT admin_id,username,role,created_at,is_active FROM admins ORDER BY created_at DESC')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admins</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><link href="assets/style.css" rel="stylesheet"></head><body><?php include __DIR__.'/partials/navbar.php';?><div class="container-fluid"><div class="row"><?php include __DIR__.'/partials/sidebar.php';?><main class="col-lg-10 p-4"><h1 class="fw-bold">Admins</h1><p class="text-muted">Manage administrator accounts.</p><?php if($msg):?><div class="alert alert-info"><?=h($msg)?></div><?php endif;?><div class="card border-0 shadow-sm mb-4"><div class="card-header bg-white"><h5>Add Admin</h5></div><div class="card-body"><form method="post" class="row g-3"><div class="col-md-4"><input name="username" class="form-control" placeholder="Username" required></div><div class="col-md-4"><input name="password" type="password" class="form-control" placeholder="Password" required></div><div class="col-md-3"><select name="role" class="form-select"><option>Staff</option><option>SuperAdmin</option></select></div><div class="col-md-1"><button class="btn btn-primary">Add</button></div></form></div></div><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>ID</th><th>Username</th><th>Role</th><th>Created At</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h((string)$r['admin_id'])?></td><td><?=h($r['username'])?></td><td><?=h($r['role'])?></td><td><?=h($r['created_at'])?></td><td><?=$r['is_active']?'Active':'Inactive'?></td></tr><?php endforeach;?></tbody></table></div></div></main></div></div></body></html>